// Execute existing production TSF checks, then exercise the new native data path.
#define main existing_tsf_main
#include "tsf_edit_test.cpp"
#undef main
#include <fstream>
struct WindowsPersonalTestAccess {
    static void file(TextService* service,const std::wstring& path){service->personalStore=std::make_unique<wangshu::WindowsPersonalStore>(path);}
    static std::string first(TextService* service){return service->candidates.empty()?"":service->candidates.front().text;}
    static void stage(TextService* service,const std::string& value){service->buffer=value;service->page=0;service->update();}
};
static int personalCount=0;
static void personalCheck(bool value,const char* label){if(!value)throw std::runtime_error(label);++personalCount;std::cout<<"PASS "<<label<<std::endl;}
static std::wstring personalGuid(){GUID id{};CoCreateGuid(&id);wchar_t buffer[40];StringFromGUID2(id,buffer,40);return buffer;}
int main(){if(existing_tsf_main()!=0)return 1;try{
    auto directory=std::filesystem::path(modulePath()).parent_path()/L"personal-tsf-tests"/personalGuid();std::filesystem::create_directories(directory);auto path=(directory/L"personal-v1.json").wstring();wangshu::WindowsPersonalStore store(path);wangshu::PersonalData data;data.words={{"nihao","专属词条"}};data.phrases={{"thanks","First line\n数学 α + 👩‍🔬"}};store.merge(data);
    auto service=new TextService;auto manager=new Manager;auto context=new Context;BOOL eat=FALSE;personalCheck(SUCCEEDED(service->Activate(manager,70)),"personal-data TSF fixture activates production service");WindowsPersonalTestAccess::file(service,path);
    for(WPARAM key:{'N','I','H','A','O'})service->OnKeyDown(context,key,0,&eat);personalCheck(WindowsPersonalTestAccess::first(service)=="专属词条","production TSF candidate chain reads custom full-pinyin word from Win32 store");service->OnKeyDown(context,VK_SPACE,0,&eat);personalCheck(eat&&context->doc.value==L"before专属词条after","actual production key routing commits personal word and preserves host prefix/suffix");
    for(WPARAM key:{'T','H','A','N','K','S'})service->OnKeyDown(context,key,0,&eat);personalCheck(WindowsPersonalTestAccess::first(service)=="First line\n数学 α + 👩‍🔬","phrase shorthand reaches production TSF candidate chain");service->OnKeyDown(context,VK_SPACE,0,&eat);personalCheck(eat&&context->doc.value==L"before专属词条First line\n数学 α + 👩‍🔬after","TSF commits complete multiline and non-BMP phrase rather than preview text");
    auto current=store.read();Sleep(20);store.modify(current.revision,[](wangshu::PersonalData& next){next.words[0].text="更新词条";});for(WPARAM key:{'N','I','H','A','O'})service->OnKeyDown(context,key,0,&eat);personalCheck(WindowsPersonalTestAccess::first(service)=="更新词条","independent manager update refreshes cached TSF overlay without restart");service->OnKeyDown(context,VK_ESCAPE,0,&eat);
    auto original=context->doc.value;context->scope=IS_PASSWORD;for(WPARAM key:{'N','I','H','A','O'})service->OnKeyDown(context,key,0,&eat);service->OnKeyDown(context,VK_SPACE,0,&eat);personalCheck(context->doc.value==original,"password input scope rejects custom candidates without altering host text");context->scope=IS_DEFAULT;
    for(WPARAM key:{'N','I','H','A','O'})service->OnKeyDown(context,key,0,&eat);context->doc.denyText=true;auto composed=context->doc.value;auto pending=TextServiceTestAccess::pendingText(service);service->OnKeyDown(context,VK_SPACE,0,&eat);personalCheck(TextServiceTestAccess::pendingText(service)==pending&&context->doc.value==composed,"editor refusal preserves custom candidate composition for retry");context->doc.denyText=false;service->OnKeyDown(context,VK_SPACE,0,&eat);personalCheck(context->doc.value==original.substr(0,original.size()-5)+L"更新词条after","retry commits personal word exactly once after editor accepts");
    service->Deactivate();service->Release();context->Release();manager->Release();personalCheck(objectCount==0,"personal overlay deactivation releases all TSF objects and cached personal state");
    service=new TextService;manager=new Manager;context=new Context;personalCheck(SUCCEEDED(service->ActivateEx(manager,71,TF_TMAE_SECUREMODE|TF_TMAE_CONSOLE)),"restricted activation retains ordinary production lifetime");WindowsPersonalTestAccess::file(service,path);WindowsPersonalTestAccess::stage(service,"nihao");personalCheck(WindowsPersonalTestAccess::first(service)=="你好","secure/console activation bypasses personal-file overlay");service->Deactivate();service->Release();context->Release();manager->Release();
    auto invalidPath=(directory/L"bad-personal.json").wstring();{std::ofstream file(std::filesystem::path(invalidPath),std::ios::binary);file<<"bad owned fixture";}service=new TextService;manager=new Manager;context=new Context;personalCheck(SUCCEEDED(service->Activate(manager,72)),"corrupt-overlay fixture still activates native keyboard");WindowsPersonalTestAccess::file(service,invalidPath);for(WPARAM key:{'N','I','H','A','O'})service->OnKeyDown(context,key,0,&eat);personalCheck(WindowsPersonalTestAccess::first(service)=="你好","unreadable personal data safely retains built-in candidates");service->OnKeyDown(context,VK_SPACE,0,&eat);personalCheck(context->doc.value==L"before你好after","built-in input remains usable despite corrupt private file");personalCheck(wangshu::WindowsPersonalStore::readExternal(invalidPath)=="bad owned fixture","candidate fallback does not reset or overwrite corrupt personal file");service->Deactivate();service->Release();context->Release();manager->Release();personalCheck(objectCount==0,"corrupt/restricted overlay paths leak no service objects");
    std::cout<<"TOTAL "<<personalCount<<" additional PASS; production PE TSF with native file overlay and mock host, real Windows GUI NOT_RUN"<<std::endl;return 0;
}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<std::endl;return 1;}}
